UPDATE ifj_etl_checkpoint SET owner_instance_id=#{instanceId}, owner_token=#{token}
WHERE task_id=#{taskId} AND checkpoint_key=#{key}
  AND (owner_token IS NULL OR EXISTS (
    SELECT 1 FROM ifj_instance previous_owner WHERE previous_owner.id=owner_instance_id
      AND previous_owner.status IN ('SUCCESS','FAILED','STOPPED','TIMED_OUT','SKIPPED')
  ))
